using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Basic")]
    [TestCategory("RJIT_CR_BC")]
    [TestCategory("RJIT_CR_BC_R")]
    [TestClass]
    public class RJIT_CR_BC_R_00001 : MsTestBase   
    {
        /*
         * Code Rule RJIT_CR_BC_R_00001 mandates that class names should not include version information. Instead, versioning should be managed through namespaces.
         */
        [TestMethod]
        public void Records_Should_Not_Contain_Versions_This_Have_To_Be_Solved_By_Namespace()
        {
            var classNameWithVersionInfo = (from @record in Records
                let match = GlobalRegex.VersionRegex().Match(@record.Name)
                where match.Success
                select new
                {
                    Error = $@"
Your records name contains version infos, please manage this in your namespaces. Extensions are not effected by this rule.
----------------------------------------------------------------------------------------------------------------------------
FullName:     {@record.FullQualifiedName}
----------------------------------------------------------------------------------------------------------------------------
Record name:   {@record.Name}
----------------------------------------------------------------------------------------------------------------------------
Matches:      {match}
----------------------------------------------------------------------------------------------------------------------------
"
                }).ToImmutableList();

            Assert.IsTrue(classNameWithVersionInfo.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_BC_R_00001

Record names with version infos detected. Found '{classNameWithVersionInfo.Count}':{Environment.NewLine}{classNameWithVersionInfo.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
